    if(kind==="bird")return <><path d="M10 30c6-14 18-16 28-7-4 11-13 15-24 11Z" {...c}/><path d="m37 23 7 3-7 3M18 25c4 1 7 4 8 8M30 22h.01" {...c}/></>;
