    if(kind==="butterfly")return <><path d="M24 22c-5-12-15-10-13-2 1 5 6 7 13 8M24 22c5-12 15-10 13-2-1 5-6 7-13 8M24 27c-5 1-10 6-7 10 3 4 7 0 7-7M24 27c5 1 10 6 7 10-3 4-7 0-7-7M24 17v18" {...c}/></>;
    if(kind==="turtle")return <><ellipse cx="25" cy="27" rx="14" ry="10" {...c}/><path d="M39 26h6l-3 4M14 21l-5-4M14 33l-5 4M34 21l4-4M34 33l4 4M19 21l12 12M31 21 19 33" {...c}/></>;
