    if(kind==="car")return <><path d="M8 30h32l-3-10H15l-7 10Z" {...c}/><path d="M10 30v7h30v-7M15 37v4M35 37v4" {...c}/><circle cx="16" cy="37" r="3" {...c}/><circle cx="34" cy="37" r="3" {...c}/></>;
