    if(kind==="clock")return <><circle cx="24" cy="26" r="17" {...c}/><path d="M24 14v12l8 5M24 6v3M24 43v3M4 26h3M41 26h3" {...c}/></>;
    if(kind==="balloon")return <><ellipse cx="24" cy="20" rx="11" ry="14" {...c}/><path d="m21 34 3 4 3-4M24 38c-6 4 5 6-1 10" {...c}/></>;
    if(kind==="apple")return <><path d="M24 17c-7-5-16 0-15 10 1 12 9 18 15 14 6 4 14-2 15-14 1-10-8-15-15-10Z" {...c}/><path d="M24 17c0-6 4-9 8-10M25 12c-5-5-9-3-10 1" {...a}/></>;
