    if(kind==="umbrella")return <><path d="M6 25c7-17 29-17 36 0-4-3-8-3-12 0-4-3-8-3-12 0-4-3-8-3-12 0Z" {...c}/><path d="M24 25v14c0 7 9 7 9 1" {...c}/></>;
    if(kind==="ball")return <><circle cx="24" cy="26" r="17" {...c}/><path d="m24 9 6 9-4 8H15l-4-8 6-7M26 26l9 7M15 26l-8 6M30 18l9-3" {...c}/></>;
    if(kind==="puzzle")return <path d="M10 12h10c-2-6 8-6 6 0h12v11c6-2 6 8 0 6v11H27c2 6-8 6-6 0H10V29c-6 2-6-8 0-6Z" {...c}/>;
    if(kind==="lemon")return <><path d="M12 30c6-16 20-20 28-12-2 15-15 23-28 12Z" {...c}/><path d="M35 16c3-4 6-5 9-4" {...a}/></>;
    if(kind==="phone")return <><path d="M14 8h20v36H14z" {...c}/><path d="M20 12h8M21 40h6" {...c}/></>;
    if(kind==="gift")return <><path d="M8 22h32v22H8zM6 16h36v8H6zM24 16v28" {...c}/><path d="M24 16c-10 0-11-9-5-9 4 0 5 5 5 9Zm0 0c10 0 11-9 5-9-4 0-5 5-5 9Z" {...a}/></>;
