// ─── TIMER BAR ───────────────────────────────────────────────────────────────
function TimerBar({ current, total, mayor }) {
  const pct = Math.max(0, Math.min(100, (current / total) * 100));
  const color = pct > 50 ? COLORS.success : pct > 25 ? COLORS.warning : COLORS.error;
  return (
    <div style={{ marginBottom: mayor ? 16 : 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
        <span style={{ fontSize: mayor ? ".9rem" : ".75rem", color: COLORS.textMuted, fontWeight: 600, display:"inline-flex", alignItems:"center", gap:6 }}><NFIcon name="clock" size={mayor?18:15} /> Tiempo</span>
        <span style={{ fontSize: mayor ? "1.1rem" : ".88rem", fontWeight: 900, color }}>
          {current}s
        </span>
      </div>
      <div style={{ height: mayor ? 12 : 8, background: COLORS.bgDark, borderRadius: 6, overflow: "hidden" }}>
        <div style={{
          height: "100%", width: `${pct}%`,
          background: `linear-gradient(90deg, ${color}, ${color}cc)`,
          borderRadius: 6,
          transition: "width 1s linear, background .5s",
        }} />
      </div>
    </div>
  );
}

// ─── VOZ / TTS ────────────────────────────────────────────────────────────────
function speakInstruction(text, { immediate = false } = {}) {
  try {
    if (!window.speechSynthesis || !text) return;
    window.speechSynthesis.cancel();
    const play = () => {
      try {
        const u = new SpeechSynthesisUtterance(text);
        u.lang = "es-CO";
        u.rate = 0.72;
        u.pitch = 1;
        u.volume = 1;
        u.onerror = () => {};
        u.onend = () => {};
        window.speechSynthesis.speak(u);
      } catch(e) {}
    };
    if (immediate) play();
    else setTimeout(play, 80);
  } catch(e) {}
}

function NFAudioReadButton({ text, label="Escuchar", mayor=false, style={} }) {
  if (!text) return null;
  return (
    <button
      type="button"
      onClick={()=>speakInstruction(String(text),{immediate:true})}
      aria-label={label}
      title={label}
      style={{
        minWidth:mayor?52:46,minHeight:mayor?52:46,borderRadius:12,
        border:`1px solid ${COLORS.border}`,background:"#fff",color:COLORS.primary,
        display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,
        padding:mayor?"9px 13px":"8px 11px",fontWeight:750,fontFamily:"inherit",
        cursor:"pointer",fontSize:mayor?".86rem":".74rem",...style
      }}
    >
      <NFIcon name="volume" size={mayor?20:18}/>
      <span>{label}</span>
    </button>
  );
}

function NFReadablePrompt({ children, text, label="Escuchar pregunta", mayor=false, style={} }) {
  return (
    <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:14,...style}}>
      <div style={{flex:1,minWidth:0}}>{children}</div>
      <NFAudioReadButton text={text} label={label} mayor={mayor}/>
    </div>
  );
}

