        const t0=useRef(Date.now());

        useEffect(()=>{
          if(phase!=="show")return;
          try{
            if(window.speechSynthesis){
              window.speechSynthesis.cancel();
              seq.forEach((n,i)=>{
                setTimeout(()=>{
                  const u=new SpeechSynthesisUtterance(String(n));
                  u.lang="es-CO";u.rate=.8;window.speechSynthesis.speak(u);
                },i*850);
              });
            }
          }catch(e){}
          const tm=setInterval(()=>setVisibleIdx(i=>{
            if(i+1>=seq.length){clearInterval(tm);setTimeout(()=>setPhase("answer"),450);return i}
            return i+1;
          }),850);
          return()=>clearInterval(tm);
        },[phase,seq]);

        if(phase==="show")return <div style={{padding:"8px 0"}}>
          <p style={{textAlign:"center",color:COLORS.textMuted,fontSize:M?".95rem":".8rem",marginBottom:8}}>Memoriza la secuencia · un número a la vez</p>
          <NFTrainingStimulusCard modoMayor={M}>
            <div style={{fontSize:M?"4.6rem":"3.8rem",fontWeight:900,color:COLORS.primary,lineHeight:1}}>{seq[visibleIdx]}</div>
          </NFTrainingStimulusCard>
          <ProgressBar value={((visibleIdx+1)/seq.length)*100} color={COLORS.primary}/>
        </div>;

        const confirm=()=>{
          const correct=answer.join("")===seq.join("");
          onDone({correct:correct?1:0,total:1,errors:correct?0:1,seconds:Math.round((Date.now()-t0.current)/1000),specificMetrics:{sequenceLength:len,clinicalProcess:"amplitud atencional / memoria de trabajo",responseMode:"reconstrucción táctil"}});
        };
