                    minHeight:M?78:68,borderRadius:"50%",
                    border:`2px solid ${done?COLORS.success:COLORS.border}`,
                    background:done?COLORS.success+"12":"#fff",
                    fontWeight:900,fontSize:M?"1.35rem":"1.1rem",
                    color:done?COLORS.success:COLORS.textPrimary,
