// ─── GESTIÓN PACIENTES (PROFESIONAL) ─────────────────────────────────────────
function GestionPacientes({ user, onVerPaciente }) {
  const [pacientes, setPacientes] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [busqueda, setBusqueda] = useState("");
  const [form, setForm] = useState({...NF_PATIENT_EMPTY_FORM});
  const [loading, setLoading] = useState(false);

  const cargar = async () => {
    try {
      const snap = await getDocs(query(collection(firestore, "pacientes"), where("profesionalId", "==", user.uid)));
      setPacientes(snap.docs.map(d => ({ id: d.id, ...d.data() })).sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn)));
    } catch(e) {}
  };

  useEffect(() => { cargar(); }, []);

  const [createdCredentials, setCreatedCredentials] = useState(null);

  const crearPaciente = async () => {
    if (!form.nombres.trim() || !form.apellidos.trim() || !form.fechaNacimiento) return;
    setLoading(true);
    try {
      const nombreCompleto=`${form.nombres.trim()} ${form.apellidos.trim()}`.trim();
      const edad=nfEdadDesdeFecha(form.fechaNacimiento);
      const baseEmail = form.email.trim() || `${form.nombres.toLowerCase().trim().replace(/\s+/g, ".")}.${Date.now()}@neuroflex.app`;
      const password = Math.random().toString(36).slice(-8).toUpperCase();
      const patientData={
        ...form,
        nombre:nombreCompleto,
        edad:Number(edad),
        email:form.email.trim(),
        loginEmail:baseEmail,
        profesionalId:user.uid,
        activo:true,
        creadoEn:new Date().toISOString(),
        actualizadoEn:new Date().toISOString(),
        sesiones:[], plan:null, eval:null,
      };

      try {
        const cred = await createUserWithEmailAndPassword(auth2, baseEmail, password);
        await setDoc(doc(firestore, "pacientes", cred.user.uid), patientData);
        setCreatedCredentials({ nombre:nombreCompleto, email:baseEmail, password });
      } catch(authErr) {
        await addDoc(collection(firestore, "pacientes"), patientData);
      }
      setShowForm(false);
      setForm({...NF_PATIENT_EMPTY_FORM});
      await cargar();
    } catch(e) { console.error(e); }
    setLoading(false);
  };

  const filtrados = pacientes.filter(p => p.nombre?.toLowerCase().includes(busqueda.toLowerCase()));

  return (
    <>
      {/* Modal de credenciales creadas */}
      {createdCredentials && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.5)", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
          <div style={{ background: COLORS.white, borderRadius: 20, padding: 32, maxWidth: 420, width: "100%", boxShadow: "0 20px 60px rgba(0,0,0,.3)" }}>
            <div style={{ textAlign: "center", marginBottom: 20 }}>
              <div style={{ width: 52, height: 52, margin: "0 auto 12px", borderRadius: "50%", background: COLORS.primarySoft, color: COLORS.primary, display: "flex", alignItems: "center", justifyContent: "center" }}><NFIcon name="patient" size={26} /></div>
              <h3 style={{ fontWeight: 700, marginBottom: 4 }}>Paciente creado</h3>
              <p style={{ color: COLORS.textMuted, fontSize: ".88rem" }}>Guarda estas credenciales para el paciente</p>
            </div>
            <div style={{ background: COLORS.bg, borderRadius: 14, padding: 20, marginBottom: 20 }}>
              <p style={{ fontWeight: 700, marginBottom: 4 }}>{createdCredentials.nombre}</p>
              <div style={{ marginBottom: 10 }}>
                <p style={{ fontSize: ".75rem", color: COLORS.textMuted, fontWeight: 600, textTransform: "uppercase", marginBottom: 2 }}>Usuario (email)</p>
                <p style={{ fontFamily: "monospace", fontSize: ".9rem", color: COLORS.primary, wordBreak: "break-all" }}>{createdCredentials.email}</p>
              </div>
              <div>
                <p style={{ fontSize: ".75rem", color: COLORS.textMuted, fontWeight: 600, textTransform: "uppercase", marginBottom: 2 }}>Contraseña</p>
                <p style={{ fontFamily: "monospace", fontSize: "1.2rem", fontWeight: 900, color: COLORS.primary, letterSpacing: 3 }}>{createdCredentials.password}</p>
              </div>
            </div>
            <div style={{ fontSize: ".82rem", color: COLORS.error, marginBottom: 16, padding: "10px 12px", borderRadius: 10, background: COLORS.error + "0D", border: `1px solid ${COLORS.error}22` }}>Anota estas credenciales ahora. No podrás volver a consultarlas desde esta pantalla.</div>
            <BtnPrimary onClick={() => setCreatedCredentials(null)} style={{ width: "100%" }}>Entendido</BtnPrimary>
          </div>
        </div>
      )}
      <div className="nf-v2-patient-list-head">
        <div className="nf-v2-patient-list-title">
          <span><NFLineIcon name="users" size={20}/></span>
          <div><div className="nf-v2-dashboard-kicker">Gestión clínica</div><h2>Pacientes</h2><p>Consulta rápidamente el estado y seguimiento de cada paciente.</p></div>
        </div>
        <div className="nf-v2-patient-list-actions">
        <input
          value={busqueda} onChange={e => setBusqueda(e.target.value)}
          placeholder="Buscar paciente..."
          style={{ flex: 1, maxWidth: 320, padding: "9px 14px", borderRadius: 10, border: `1.5px solid ${COLORS.border}`, fontSize: ".88rem", outline: "none" }}
        />
        <BtnPrimary onClick={() => setShowForm(true)}><span style={{display:"inline-flex",alignItems:"center",gap:7}}><NFIcon name="plus" size={17}/>Nuevo paciente</span></BtnPrimary>
        </div>
      </div>

      {showForm && (
        <Card className="nf-v2-patient-form" style={{ marginBottom:24,padding:28 }}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:12,marginBottom:4}}>
            <div>
              <div style={{fontSize:".67rem",fontWeight:850,color:COLORS.primary}}>INGRESO DEL PACIENTE</div>
              <h3 style={{fontWeight:800,margin:"4px 0",fontSize:"1.08rem"}}>Información personal y motivo de consulta</h3>
              <p style={{margin:0,color:COLORS.textMuted,fontSize:".72rem"}}>Esta información formará parte de la ficha permanente del paciente y podrá editarse después.</p>
            </div>
            <BtnSecondary onClick={()=>{setShowForm(false);setForm({...NF_PATIENT_EMPTY_FORM})}}>Cancelar</BtnSecondary>
          </div>

          <NFPatientSection title="Identificación" subtitle="Datos básicos para identificar al paciente. La edad se calcula automáticamente desde la fecha de nacimiento.">
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
              <Input label="Nombres *" value={form.nombres} onChange={e=>setForm(f=>({...f,nombres:e.target.value}))}/>
              <Input label="Apellidos *" value={form.apellidos} onChange={e=>setForm(f=>({...f,apellidos:e.target.value}))}/>
              <NFPatientSelect label="Tipo de documento" value={form.tipoDocumento} onChange={e=>setForm(f=>({...f,tipoDocumento:e.target.value}))}>
                <option value="">Seleccionar</option><option>CC</option><option>TI</option><option>CE</option><option>Pasaporte</option><option>Registro civil</option><option>Otro</option>
              </NFPatientSelect>
              <Input label="Número de documento" value={form.numeroDocumento} onChange={e=>setForm(f=>({...f,numeroDocumento:e.target.value}))}/>
              <Input label="Fecha de nacimiento *" type="date" value={form.fechaNacimiento} onChange={e=>setForm(f=>({...f,fechaNacimiento:e.target.value}))}/>
              <div style={{marginBottom:16}}>
                <label style={{display:"block",fontWeight:600,fontSize:".82rem",color:COLORS.textSecond,marginBottom:6}}>Edad</label>
                <div style={{padding:"10px 12px",borderRadius:10,background:COLORS.bg,border:`1.5px solid ${COLORS.border}`,fontSize:".88rem",fontWeight:750}}>{form.fechaNacimiento ? `${nfEdadDesdeFecha(form.fechaNacimiento)} años` : "Se calcula automáticamente"}</div>
              </div>
              <NFPatientSelect label="Género" value={form.genero} onChange={e=>setForm(f=>({...f,genero:e.target.value}))}>
                <option value="">Seleccionar</option><option>Femenino</option><option>Masculino</option><option>Otro</option><option>Prefiere no indicar</option>
              </NFPatientSelect>
              <NFPatientSelect label="Lateralidad" value={form.lateralidad} onChange={e=>setForm(f=>({...f,lateralidad:e.target.value}))}>
                <option value="">Seleccionar</option><option>Diestro</option><option>Zurdo</option><option>Ambidiestro</option><option>No determinada</option>
              </NFPatientSelect>
            </div>
          </NFPatientSection>

          <NFPatientSection title="Información sociodemográfica">
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
              <NFPatientSelect label="Estado civil" value={form.estadoCivil} onChange={e=>setForm(f=>({...f,estadoCivil:e.target.value}))}>
                <option value="">Seleccionar</option><option>Soltero/a</option><option>Casado/a</option><option>Unión libre</option><option>Separado/a</option><option>Divorciado/a</option><option>Viudo/a</option><option>Otro</option>
              </NFPatientSelect>
              <Input label="Ocupación / profesión" value={form.ocupacion} onChange={e=>setForm(f=>({...f,ocupacion:e.target.value}))}/>
              <Input label="Escolaridad" value={form.escolaridad} onChange={e=>setForm(f=>({...f,escolaridad:e.target.value}))} placeholder="Ej: Universitaria completa"/>
            </div>
          </NFPatientSection>

          <NFPatientSection title="Contacto">
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
              <Input label="Correo electrónico" type="email" value={form.email} onChange={e=>setForm(f=>({...f,email:e.target.value}))}/>
              <Input label="Teléfono" value={form.telefono} onChange={e=>setForm(f=>({...f,telefono:e.target.value}))}/>
              <Input label="Dirección" value={form.direccion} onChange={e=>setForm(f=>({...f,direccion:e.target.value}))}/>
              <Input label="Ciudad" value={form.ciudad} onChange={e=>setForm(f=>({...f,ciudad:e.target.value}))}/>
              <Input label="Departamento / estado" value={form.departamento} onChange={e=>setForm(f=>({...f,departamento:e.target.value}))}/>
              <Input label="País" value={form.pais} onChange={e=>setForm(f=>({...f,pais:e.target.value}))}/>
            </div>
          </NFPatientSection>

          <NFPatientSection title="Contacto de emergencia / responsable" subtitle="Puede dejarse en blanco cuando no aplique.">
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
              <Input label="Nombre completo" value={form.contactoEmergenciaNombre} onChange={e=>setForm(f=>({...f,contactoEmergenciaNombre:e.target.value}))}/>
              <Input label="Parentesco / relación" value={form.contactoEmergenciaRelacion} onChange={e=>setForm(f=>({...f,contactoEmergenciaRelacion:e.target.value}))}/>
              <Input label="Teléfono" value={form.contactoEmergenciaTelefono} onChange={e=>setForm(f=>({...f,contactoEmergenciaTelefono:e.target.value}))}/>
              <Input label="Correo" type="email" value={form.contactoEmergenciaEmail} onChange={e=>setForm(f=>({...f,contactoEmergenciaEmail:e.target.value}))}/>
            </div>
          </NFPatientSection>

          <NFPatientSection title="Información clínica inicial" subtitle="El motivo de consulta es de escritura libre; no se limita a categorías predeterminadas.">
            <div style={{marginBottom:16}}>
              <label style={{display:"block",fontWeight:600,fontSize:".82rem",color:COLORS.textSecond,marginBottom:6}}>Motivo de consulta *</label>
              <textarea value={form.motivo} onChange={e=>setForm(f=>({...f,motivo:e.target.value}))} placeholder="Describe con las palabras del paciente, familiar o remitente la razón principal de consulta..."
                style={{width:"100%",minHeight:105,padding:"12px 14px",borderRadius:10,border:`1.5px solid ${COLORS.border}`,fontSize:".9rem",resize:"vertical",fontFamily:"inherit",color:COLORS.textPrimary}}/>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(230px,1fr))",gap:"0 18px"}}>
              <Input label="Remitido por / profesional remitente" value={form.remitidoPor} onChange={e=>setForm(f=>({...f,remitidoPor:e.target.value}))}/>
              <Input label="Diagnóstico / condición conocida" value={form.diagnostico} onChange={e=>setForm(f=>({...f,diagnostico:e.target.value}))}/>
            </div>
            <div style={{marginBottom:16}}>
              <label style={{display:"block",fontWeight:600,fontSize:".82rem",color:COLORS.textSecond,marginBottom:6}}>Observaciones iniciales</label>
              <textarea value={form.observacionesIniciales} onChange={e=>setForm(f=>({...f,observacionesIniciales:e.target.value}))}
                style={{width:"100%",minHeight:85,padding:"12px 14px",borderRadius:10,border:`1.5px solid ${COLORS.border}`,fontSize:".9rem",resize:"vertical",fontFamily:"inherit"}}/>
            </div>
          </NFPatientSection>

          <div style={{display:"flex",justifyContent:"flex-end",gap:10,marginTop:8}}>
            <BtnSecondary onClick={()=>{setShowForm(false);setForm({...NF_PATIENT_EMPTY_FORM})}}>Cancelar</BtnSecondary>
            <BtnPrimary onClick={crearPaciente} disabled={loading || !form.nombres.trim() || !form.apellidos.trim() || !form.fechaNacimiento || !form.motivo.trim()}>
              {loading ? "Guardando..." : "Crear paciente"}
            </BtnPrimary>
          </div>
        </Card>
      )}

      <Card className="nf-v2-patient-table-card" style={{ padding: 0, overflow: "hidden" }}>
        <table className="nf-v2-patient-table" style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ background: COLORS.bg }}>
              {["Paciente", "Edad", "Diagnóstico", "Estado", "Última sesión", ""].map((h, i) => (
                <th key={i} style={{ padding: "12px 20px", textAlign: "left", fontSize: ".75rem", fontWeight: 600, color: COLORS.textMuted, textTransform: "uppercase", letterSpacing: .5 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtrados.length === 0 ? (
              <tr><td colSpan={6} style={{ padding: 32, textAlign: "center", color: COLORS.textMuted }}>
                {busqueda ? "No se encontraron pacientes." : "Aún no tienes pacientes. Crea el primero."}
              </td></tr>
            ) : filtrados.map(p => (
              <tr key={p.id} style={{ borderTop: `1px solid ${COLORS.border}`, cursor: "pointer" }}
                onClick={() => onVerPaciente(p)}
                onMouseEnter={e => e.currentTarget.style.background = COLORS.bg}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}
              >
                <td style={{ padding: "14px 20px" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <Avatar name={p.nombre} size={34} />
                    <div>
                      <p style={{ fontWeight: 600, fontSize: ".88rem", margin: 0 }}>{p.nombre}</p>
                      <p style={{ color: COLORS.textMuted, fontSize: ".72rem", margin: 0 }}>{p.email || "Sin correo"}</p>
                    </div>
                  </div>
                </td>
                <td style={{ padding: "14px 20px", fontSize: ".85rem" }}>{p.edad} años</td>
                <td style={{ padding: "14px 20px", fontSize: ".85rem", color: COLORS.textSecond }}>{p.diagnostico || "—"}</td>
                <td style={{ padding: "14px 20px" }}><Badge label={p.activo ? "Activo" : "Inactivo"} color={p.activo ? COLORS.success : COLORS.textMuted} /></td>
                <td style={{ padding: "14px 20px", fontSize: ".82rem", color: COLORS.textMuted }}>
                  {p.sesiones?.length > 0 ? new Date(p.sesiones[p.sesiones.length-1]?.date).toLocaleDateString("es") : "Sin sesiones"}
                </td>
                <td style={{ padding: "14px 20px" }}>
                  <span style={{ color: COLORS.primary, fontSize: ".82rem", fontWeight: 600 }}>Ver perfil →</span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
    </>
  );
}

// ─── HISTORIA CLÍNICA ─────────────────────────────────────────────────────────
function HistoriaClinicaEditor({ paciente, onUpdate }) {
  const [hc, setHc] = useState(paciente.hc || "");
  const [antMed, setAntMed] = useState(paciente.antMed || "");
  const [antQx, setAntQx] = useState(paciente.antQx || "");
  const [antFam, setAntFam] = useState(paciente.antFam || "");
  const [medicamentos, setMedicamentos] = useState(paciente.medicamentos || "");
  const [alergias, setAlergias] = useState(paciente.alergias || "");
  const [evolucion, setEvolucion] = useState(paciente.evolucion || "");
  const [notasHC, setNotasHC] = useState(paciente.notasHC || "");
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const guardar = async () => {
    setSaving(true);
    try {
      const data = { hc, antMed, antQx, antFam, medicamentos, alergias, evolucion, notasHC };
      await updateDoc(doc(firestore, "pacientes", paciente.id), data);
      onUpdate({ ...paciente, ...data });
      setSaved(true);
      setTimeout(() => setSaved(false), 2500);
    } catch(e) { console.error(e); }
    setSaving(false);
  };

  const textareaStyle = {
    width: "100%", padding: "12px 14px", borderRadius: 12,
    border: `1px solid ${COLORS.border}`, fontSize: ".9rem", resize: "vertical",
    fontFamily: "inherit", color: COLORS.textPrimary, lineHeight: 1.65,
    outline: "none", background: COLORS.white, transition: "border-color .15s ease, box-shadow .15s ease"
  };

  const field = (label, value, setter, rows, placeholder) => (
    <div className="nf-hc-field">
      <label>{label}</label>
      <textarea
        value={value}
        onChange={e => setter(e.target.value)}
        rows={rows}
        placeholder={placeholder}
        style={textareaStyle}
        onFocus={e => {
          e.target.style.borderColor = COLORS.primary;
          e.target.style.boxShadow = "0 0 0 3px rgba(40,127,131,.08)";
        }}
        onBlur={e => {
          e.target.style.borderColor = COLORS.border;
          e.target.style.boxShadow = "none";
        }}
      />
    </div>
  );

  return (
    <div className="nf-hc nf-v2-hc">
      <div className="nf-hc-intro">
        <div className="nf-hc-intro__icon"><NFLineIcon name="clinical" size={21}/></div>
        <div>
          <h2>Historia clínica</h2>
          <p>Información clínica complementaria para orientar el seguimiento. Los cambios se guardan únicamente al seleccionar “Guardar historia clínica”.</p>
        </div>
      </div>

      <div className="nf-hc-grid nf-v2-hc-grid">
        <Card className="nf-hc-card nf-v2-hc-card">
          <div className="nf-hc-card__title">
            <span><NFLineIcon name="clinical" size={18}/></span>
            <div><h3>Antecedentes</h3><p>Información médica y familiar relevante.</p></div>
          </div>
          {field("Antecedentes médicos", antMed, setAntMed, 4, "HTA, DM, hipotiroidismo, ACV previo, TCE, epilepsia...")}
          {field("Antecedentes quirúrgicos", antQx, setAntQx, 3, "Cirugías previas, fechas, complicaciones...")}
          {field("Antecedentes familiares", antFam, setAntFam, 3, "Demencia, Alzheimer, Parkinson, ACV u otros antecedentes familiares...")}
        </Card>

        <Card className="nf-hc-card nf-v2-hc-card">
          <div className="nf-hc-card__title">
            <span><NFLineIcon name="plan" size={18}/></span>
            <div><h3>Condición actual</h3><p>Tratamiento, alertas y motivo de consulta.</p></div>
          </div>
          {field("Medicamentos actuales", medicamentos, setMedicamentos, 4, "Nombre, dosis y frecuencia...")}
          {field("Alergias", alergias, setAlergias, 2, "Medicamentos, alimentos, sustancias...")}
          {field("Motivo de consulta / Historia actual", hc, setHc, 4, "Descripción del motivo de consulta, inicio, evolución y observaciones relevantes...")}
        </Card>
      </div>

      <Card className="nf-hc-evolution nf-v2-hc-notes" style={{marginBottom:16}}>
        <div className="nf-hc-card__title">
          <span><NFLineIcon name="note" size={18}/></span>
          <div><h3>Notas</h3><p>Espacio libre para registrar información de la historia del paciente que consideres importante conservar a la vista.</p></div>
        </div>
        <textarea
          value={notasHC}
          onChange={e => setNotasHC(e.target.value)}
          rows={6}
          placeholder="Anota aquí datos relevantes, detalles a recordar, información aportada por el paciente o familiar, aspectos para explorar posteriormente..."
          style={{ ...textareaStyle, minHeight: 145 }}
          onFocus={e => {
            e.target.style.borderColor = COLORS.primary;
            e.target.style.boxShadow = "0 0 0 3px rgba(40,127,131,.08)";
          }}
          onBlur={e => {
            e.target.style.borderColor = COLORS.border;
            e.target.style.boxShadow = "none";
          }}
        />
      </Card>

      <Card className="nf-hc-evolution nf-v2-hc-evolution">
        <div className="nf-hc-card__title">
          <span><NFLineIcon name="followup" size={18}/></span>
          <div><h3>Evolución y observaciones clínicas</h3><p>Registro cronológico del proceso y de los ajustes clínicos.</p></div>
        </div>
        <textarea
          value={evolucion}
          onChange={e => setEvolucion(e.target.value)}
          rows={7}
          placeholder={`${new Date().toLocaleDateString("es")} — Observaciones de la sesión, cambios observados, ajustes al plan...`}
          style={{ ...textareaStyle, minHeight: 170 }}
          onFocus={e => {
            e.target.style.borderColor = COLORS.primary;
            e.target.style.boxShadow = "0 0 0 3px rgba(40,127,131,.08)";
          }}
          onBlur={e => {
            e.target.style.borderColor = COLORS.border;
            e.target.style.boxShadow = "none";
          }}
        />
        <div className="nf-hc-evolution__actions">
          <BtnSecondary onClick={() => {
            const fecha = new Date().toLocaleDateString("es");
            setEvolucion(prev => prev ? `${prev}\n\n${fecha} — ` : `${fecha} — `);
          }}>
            <span style={{display:"inline-flex",alignItems:"center",gap:7}}><NFIcon name="calendar" size={16}/>Agregar entrada de hoy</span>
          </BtnSecondary>
        </div>
      </Card>

      <div className="nf-hc-savebar">
        <div>
          {saved
            ? <span className="nf-hc-saved"><NFLineIcon name="next" size={16}/>Guardado correctamente</span>
            : <span className="nf-hc-savehint">Los cambios permanecen sin guardar hasta confirmar.</span>}
        </div>
        <BtnPrimary onClick={guardar} disabled={saving} style={{ minWidth: 190 }}>
          {saving ? "Guardando..." : "Guardar historia clínica"}
        </BtnPrimary>
      </div>
    </div>
  );
}



function NFPatientPersonalInfoEditor({paciente,onUpdate}){
  const initial={
    ...NF_PATIENT_EMPTY_FORM,
    ...paciente,
    nombres:paciente.nombres || (paciente.nombre||"").trim().split(/\s+/).slice(0,1).join(" "),
    apellidos:paciente.apellidos || (paciente.nombre||"").trim().split(/\s+/).slice(1).join(" "),
  };
  const [form,setForm]=useState(initial);
  const [editing,setEditing]=useState(false);
  const [saving,setSaving]=useState(false);
  useEffect(()=>{
    setForm({
      ...NF_PATIENT_EMPTY_FORM,...paciente,
      nombres:paciente.nombres || (paciente.nombre||"").trim().split(/\s+/).slice(0,1).join(" "),
      apellidos:paciente.apellidos || (paciente.nombre||"").trim().split(/\s+/).slice(1).join(" "),
    });
  },[paciente]);

  const save=async()=>{
    setSaving(true);
    try{
      const nombre=`${form.nombres||""} ${form.apellidos||""}`.trim() || paciente.nombre;
      const edad=form.fechaNacimiento ? nfEdadDesdeFecha(form.fechaNacimiento) : paciente.edad;
      const patch={
        nombres:form.nombres||"",apellidos:form.apellidos||"",nombre,
        tipoDocumento:form.tipoDocumento||"",numeroDocumento:form.numeroDocumento||"",
        fechaNacimiento:form.fechaNacimiento||"",edad:Number(edad)||0,
        genero:form.genero||"",lateralidad:form.lateralidad||"",
        estadoCivil:form.estadoCivil||"",ocupacion:form.ocupacion||"",escolaridad:form.escolaridad||"",
        email:form.email||"",telefono:form.telefono||"",direccion:form.direccion||"",
        ciudad:form.ciudad||"",departamento:form.departamento||"",pais:form.pais||"",
        contactoEmergenciaNombre:form.contactoEmergenciaNombre||"",
        contactoEmergenciaRelacion:form.contactoEmergenciaRelacion||"",
        contactoEmergenciaTelefono:form.contactoEmergenciaTelefono||"",
        contactoEmergenciaEmail:form.contactoEmergenciaEmail||"",
        motivo:form.motivo||"",remitidoPor:form.remitidoPor||"",
        diagnostico:form.diagnostico||"",observacionesIniciales:form.observacionesIniciales||"",
        actualizadoEn:new Date().toISOString(),
      };
      await updateDoc(doc(firestore,"pacientes",paciente.id),patch);
      onUpdate({...paciente,...patch});
      setEditing(false);
    }catch(e){console.error("Error actualizando ficha:",e);alert("No se pudo actualizar la ficha del paciente.");}
    setSaving(false);
  };

  const value=(v)=>v || "No registrado";
  if(!editing)return <div style={{display:"grid",gap:16}}>
    <Card style={{padding:24}}>
      <div style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"flex-start",marginBottom:18}}>
        <div><div style={{fontSize:".67rem",fontWeight:850,color:COLORS.primary}}>FICHA DEL PACIENTE</div><h3 style={{margin:"4px 0"}}>Información personal</h3></div>
        <BtnSecondary onClick={()=>setEditing(true)}>Editar información</BtnSecondary>
      </div>
      {[
        ["Identificación",[
          ["Nombre",paciente.nombre],["Documento",[paciente.tipoDocumento,paciente.numeroDocumento].filter(Boolean).join(" ")],
          ["Fecha de nacimiento",paciente.fechaNacimiento],["Edad",paciente.edad!=null?`${paciente.edad} años`:""],
          ["Género",paciente.genero],["Lateralidad",paciente.lateralidad],["Estado civil",paciente.estadoCivil],
          ["Ocupación / profesión",paciente.ocupacion],["Escolaridad",paciente.escolaridad],
        ]],
        ["Contacto",[
          ["Correo",paciente.email],["Teléfono",paciente.telefono],["Dirección",paciente.direccion],
          ["Ciudad",paciente.ciudad],["Departamento / estado",paciente.departamento],["País",paciente.pais],
        ]],
        ["Contacto de emergencia / responsable",[
          ["Nombre",paciente.contactoEmergenciaNombre],["Relación",paciente.contactoEmergenciaRelacion],
          ["Teléfono",paciente.contactoEmergenciaTelefono],["Correo",paciente.contactoEmergenciaEmail],
        ]],
      ].map(([title,rows])=><div key={title} style={{padding:"16px 0",borderTop:`1px solid ${COLORS.border}`}}>
        <h4 style={{margin:"0 0 10px",fontSize:".82rem"}}>{title}</h4>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(190px,1fr))",gap:10}}>
          {rows.map(([k,v])=><div key={k} style={{padding:10,borderRadius:9,background:COLORS.bg}}>
            <div style={{fontSize:".61rem",fontWeight:750,color:COLORS.textMuted,textTransform:"uppercase"}}>{k}</div>
            <div style={{fontSize:".76rem",fontWeight:650,marginTop:3}}>{value(v)}</div>
          </div>)}
        </div>
      </div>)}
    </Card>
    <Card style={{padding:24}}>
      <div style={{fontSize:".67rem",fontWeight:850,color:COLORS.accent}}>INFORMACIÓN CLÍNICA INICIAL</div>
      <h3 style={{margin:"4px 0 14px"}}>Motivo de consulta</h3>
      <div style={{padding:16,borderRadius:11,background:COLORS.bg,fontSize:".78rem",lineHeight:1.65,whiteSpace:"pre-wrap"}}>{value(paciente.motivo)}</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:10,marginTop:12}}>
        <div><strong style={{fontSize:".68rem"}}>Remitido por</strong><p style={{fontSize:".75rem",color:COLORS.textSecond}}>{value(paciente.remitidoPor)}</p></div>
        <div><strong style={{fontSize:".68rem"}}>Diagnóstico / condición conocida</strong><p style={{fontSize:".75rem",color:COLORS.textSecond}}>{value(paciente.diagnostico)}</p></div>
      </div>
      {paciente.observacionesIniciales&&<div style={{marginTop:8}}><strong style={{fontSize:".68rem"}}>Observaciones iniciales</strong><p style={{fontSize:".75rem",color:COLORS.textSecond,whiteSpace:"pre-wrap"}}>{paciente.observacionesIniciales}</p></div>}
    </Card>
  </div>;

  return <Card style={{padding:26}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
      <div><div style={{fontSize:".67rem",fontWeight:850,color:COLORS.primary}}>EDITAR FICHA</div><h3 style={{margin:"4px 0"}}>Información del paciente</h3></div>
      <BtnSecondary onClick={()=>setEditing(false)}>Cancelar</BtnSecondary>
    </div>
    <NFPatientSection title="Identificación">
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
        <Input label="Nombres" value={form.nombres} onChange={e=>setForm(f=>({...f,nombres:e.target.value}))}/>
        <Input label="Apellidos" value={form.apellidos} onChange={e=>setForm(f=>({...f,apellidos:e.target.value}))}/>
        <NFPatientSelect label="Tipo de documento" value={form.tipoDocumento} onChange={e=>setForm(f=>({...f,tipoDocumento:e.target.value}))}><option value="">Seleccionar</option><option>CC</option><option>TI</option><option>CE</option><option>Pasaporte</option><option>Registro civil</option><option>Otro</option></NFPatientSelect>
        <Input label="Número de documento" value={form.numeroDocumento} onChange={e=>setForm(f=>({...f,numeroDocumento:e.target.value}))}/>
        <Input label="Fecha de nacimiento" type="date" value={form.fechaNacimiento} onChange={e=>setForm(f=>({...f,fechaNacimiento:e.target.value}))}/>
        <NFPatientSelect label="Género" value={form.genero} onChange={e=>setForm(f=>({...f,genero:e.target.value}))}><option value="">Seleccionar</option><option>Femenino</option><option>Masculino</option><option>Otro</option><option>Prefiere no indicar</option></NFPatientSelect>
        <NFPatientSelect label="Lateralidad" value={form.lateralidad} onChange={e=>setForm(f=>({...f,lateralidad:e.target.value}))}><option value="">Seleccionar</option><option>Diestro</option><option>Zurdo</option><option>Ambidiestro</option><option>No determinada</option></NFPatientSelect>
        <Input label="Estado civil" value={form.estadoCivil} onChange={e=>setForm(f=>({...f,estadoCivil:e.target.value}))}/>
        <Input label="Ocupación / profesión" value={form.ocupacion} onChange={e=>setForm(f=>({...f,ocupacion:e.target.value}))}/>
        <Input label="Escolaridad" value={form.escolaridad} onChange={e=>setForm(f=>({...f,escolaridad:e.target.value}))}/>
      </div>
    </NFPatientSection>
    <NFPatientSection title="Contacto">
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
        <Input label="Correo" type="email" value={form.email} onChange={e=>setForm(f=>({...f,email:e.target.value}))}/>
        <Input label="Teléfono" value={form.telefono} onChange={e=>setForm(f=>({...f,telefono:e.target.value}))}/>
        <Input label="Dirección" value={form.direccion} onChange={e=>setForm(f=>({...f,direccion:e.target.value}))}/>
        <Input label="Ciudad" value={form.ciudad} onChange={e=>setForm(f=>({...f,ciudad:e.target.value}))}/>
        <Input label="Departamento / estado" value={form.departamento} onChange={e=>setForm(f=>({...f,departamento:e.target.value}))}/>
        <Input label="País" value={form.pais} onChange={e=>setForm(f=>({...f,pais:e.target.value}))}/>
      </div>
    </NFPatientSection>
    <NFPatientSection title="Contacto de emergencia / responsable">
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(210px,1fr))",gap:"0 18px"}}>
        <Input label="Nombre completo" value={form.contactoEmergenciaNombre} onChange={e=>setForm(f=>({...f,contactoEmergenciaNombre:e.target.value}))}/>
        <Input label="Parentesco / relación" value={form.contactoEmergenciaRelacion} onChange={e=>setForm(f=>({...f,contactoEmergenciaRelacion:e.target.value}))}/>
        <Input label="Teléfono" value={form.contactoEmergenciaTelefono} onChange={e=>setForm(f=>({...f,contactoEmergenciaTelefono:e.target.value}))}/>
        <Input label="Correo" value={form.contactoEmergenciaEmail} onChange={e=>setForm(f=>({...f,contactoEmergenciaEmail:e.target.value}))}/>
      </div>
    </NFPatientSection>
    <NFPatientSection title="Información clínica inicial">
      <div style={{marginBottom:16}}><label style={{display:"block",fontWeight:600,fontSize:".82rem",color:COLORS.textSecond,marginBottom:6}}>Motivo de consulta</label><textarea value={form.motivo} onChange={e=>setForm(f=>({...f,motivo:e.target.value}))} style={{width:"100%",minHeight:105,padding:"12px 14px",borderRadius:10,border:`1.5px solid ${COLORS.border}`,fontFamily:"inherit",resize:"vertical"}}/></div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:"0 18px"}}>
        <Input label="Remitido por" value={form.remitidoPor} onChange={e=>setForm(f=>({...f,remitidoPor:e.target.value}))}/>
        <Input label="Diagnóstico / condición conocida" value={form.diagnostico} onChange={e=>setForm(f=>({...f,diagnostico:e.target.value}))}/>
      </div>
      <div><label style={{display:"block",fontWeight:600,fontSize:".82rem",color:COLORS.textSecond,marginBottom:6}}>Observaciones iniciales</label><textarea value={form.observacionesIniciales} onChange={e=>setForm(f=>({...f,observacionesIniciales:e.target.value}))} style={{width:"100%",minHeight:85,padding:"12px 14px",borderRadius:10,border:`1.5px solid ${COLORS.border}`,fontFamily:"inherit",resize:"vertical"}}/></div>
    </NFPatientSection>
    <div style={{display:"flex",justifyContent:"flex-end",gap:10,marginTop:12}}><BtnSecondary onClick={()=>setEditing(false)}>Cancelar</BtnSecondary><BtnPrimary onClick={save} disabled={saving}>{saving?"Guardando...":"Guardar cambios"}</BtnPrimary></div>
  </Card>;
}

function PerfilPaciente({ paciente: pacienteInit, onVolver, profesionalUid, onIniciarSesion, onPacienteUpdate }) {
  const [paciente, setPaciente] = useState(pacienteInit);
  useEffect(() => { setPaciente(pacienteInit); }, [pacienteInit]);
  const setPac = (p) => { setPaciente(p); onPacienteUpdate?.(p); };
  const [tab, setTab] = useState("info");
  const [showEval, setShowEval] = useState(false);
  const [reportSessionNumber, setReportSessionNumber] = useState(null);
  const TABS = [
    { id: "info", label: "Resumen clínico" },
    { id: "datos", label: "Información" },
    { id: "hc", label: "Historia clínica" },
    { id: "perfil-cognitivo", label: "Perfil cognitivo" },
    { id: "intervencion", label: "Intervención" },
    { id: "sesiones", label: "Sesiones" },
    { id: "progreso", label: "Progreso" },
    { id: "reportes", label: "Reportes" },
  ];

  const saveEvaluationDraft = async (draft) => {
    try {
      await updateDoc(doc(firestore, "pacientes", paciente.id), { evaluationDraft: draft });
      setPac({...paciente,evaluationDraft:draft});
    } catch(e) {
      console.error("Error guardando progreso de evaluación:", e);
      alert("No se pudo guardar el progreso de la evaluación.");
      throw e;
    }
  };

  const saveEval = async (evalData) => {
    try {
      const previousHistory = getEvaluationHistory(paciente);
      const normalized = normalizeEvaluationRecord(evalData, {
        validityStatus: "valid",
        evaluationVersion: NEUROFLEX_EVALUATION_VERSION,
      });

      const nextHistory = [
        ...previousHistory.filter(r => r.evaluationId !== normalized.evaluationId),
        normalized,
      ].sort((a,b) => new Date(a.date || 0) - new Date(b.date || 0));

      const preserveBaseline = normalized.preserveCurrentBaseline === true || normalized.assessmentMode === "selective_reassessment" || normalized.assessmentMode === "screening";
      const updated = {
        ...paciente,
        eval: preserveBaseline ? paciente.eval : normalized,
        evaluationHistory: nextHistory,
        activeEvaluationId: preserveBaseline ? paciente.activeEvaluationId : normalized.evaluationId,
        ...(normalized.assessmentMode==="full" ? {evaluationDraft:null} : {}),
      };

      await updateDoc(doc(firestore, "pacientes", paciente.id), {
        eval: preserveBaseline ? (paciente.eval || null) : normalized,
        evaluationHistory: nextHistory,
        activeEvaluationId: preserveBaseline ? (paciente.activeEvaluationId || null) : normalized.evaluationId,
        ...(normalized.assessmentMode==="full" ? {evaluationDraft:null} : {}),
      });

      setPac(updated);
      setShowEval(false);
      setTab("perfil-cognitivo");
    } catch(e) {
      console.error("Error guardando evaluación:", e);
      alert("No se pudo guardar la evaluación. Los resultados no se reemplazaron.");
    }
  };

  const saveLongitudinalDecision = async (decisionRecord) => {
    const previous=paciente?.longitudinalClinicalDecisions || [];
    const next=[...previous,decisionRecord];
    await updateDoc(doc(firestore, "pacientes", paciente.id), {
      longitudinalClinicalDecisions: next,
    });
    setPac({...paciente,longitudinalClinicalDecisions:next});
  };

  if (showEval) return (
    <EvaluacionAdulto
      paciente={paciente}
      onFinish={saveEval}
      onSaveDraft={saveEvaluationDraft}
      onCancel={() => setShowEval(false)}
    />
  );

  return (
    <>
      {/* Header paciente */}
      <Card className="nf-v2-patient-profile-head" style={{ marginBottom: 22, padding: "20px 24px" }}>
        <div className="nf-v2-patient-profile-head__row" style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <button onClick={onVolver} style={{ background: "transparent", border: "none", color: COLORS.textMuted, cursor: "pointer", fontSize: "1.1rem" }}>←</button>
            <Avatar name={paciente.nombre} size={48} />
            <div>
              <h2 style={{ fontWeight: 700, fontSize: "1.15rem", margin: "0 0 4px" }}>{paciente.nombre}</h2>
              <p style={{ color: COLORS.textMuted, fontSize: ".82rem", margin: 0 }}>
                {paciente.edad} años · {paciente.diagnostico || "Sin diagnóstico"} · {paciente.sesiones?.length || 0} sesiones
              </p>
            </div>
          </div>
          <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
            <Badge label={paciente.activo ? "Activo" : "Inactivo"} color={paciente.activo ? COLORS.success : COLORS.textMuted} />
            {/* Toggle modo adulto mayor */}
            <button onClick={async () => {
              const nuevo = !paciente.modoMayor;
              await updateDoc(doc(firestore, "pacientes", paciente.id), { modoMayor: nuevo });
              setPac({ ...paciente, modoMayor: nuevo });
            }} style={{
              padding: "5px 12px", borderRadius: 20, border: `1.5px solid ${paciente.modoMayor ? COLORS.accent : COLORS.border}`,
              background: paciente.modoMayor ? COLORS.accent + "15" : "transparent",
              color: paciente.modoMayor ? COLORS.accent : COLORS.textMuted,
              cursor: "pointer", fontSize: ".78rem", fontWeight: 600, fontFamily: "inherit"
            }}>
              <span style={{display:"inline-flex",alignItems:"center",gap:6}}><NFLineIcon name="person" size={15}/>{paciente.modoMayor ? "Modo accesible ON" : "Modo accesible"}</span>
            </button>
            {/* Toggle demostración */}
            <button onClick={async () => {
              const nuevo = !paciente.showDemo;
              await updateDoc(doc(firestore, "pacientes", paciente.id), { showDemo: nuevo });
              setPac({ ...paciente, showDemo: nuevo });
            }} style={{
              padding: "5px 12px", borderRadius: 20, border: `1.5px solid ${paciente.showDemo ? COLORS.primary : COLORS.border}`,
              background: paciente.showDemo ? COLORS.primary + "15" : "transparent",
              color: paciente.showDemo ? COLORS.primary : COLORS.textMuted,
              cursor: "pointer", fontSize: ".78rem", fontWeight: 600, fontFamily: "inherit"
            }}>
              <span style={{display:"inline-flex",alignItems:"center",gap:6}}><NFLineIcon name="next" size={15}/>{paciente.showDemo ? "Demo ON" : "Demo"}</span>
            </button>
            {getActiveEvaluation(paciente)
              ? <BtnPrimary onClick={onIniciarSesion} style={{ padding: "8px 16px", fontSize: ".82rem" }}><span style={{display:"inline-flex",alignItems:"center",gap:7}}><NFLineIcon name="next" size={16}/>Iniciar sesión</span></BtnPrimary>
              : <BtnPrimary onClick={() => setShowEval(true)} style={{ padding: "8px 16px", fontSize: ".82rem", background: `linear-gradient(135deg, ${COLORS.accent}, ${COLORS.primary})` }}>
                  <span style={{display:"inline-flex",alignItems:"center",gap:7}}><NFLineIcon name="brain" size={16}/>{getEvaluationHistory(paciente).length ? "Reevaluar" : "Evaluar"}</span>
                </BtnPrimary>
            }
          </div>
        </div>
      </Card>

      {/* Tabs */}
      <div className="nf-profile-tabs">
        {TABS.map((t,idx) => (
          <button key={t.id} className={`nf-profile-tab ${tab === t.id ? "is-active" : ""}`} data-accent={idx % 4} onClick={() => setTab(t.id)} title={PROFILE_TAB_INFO[t.id]?.help}>
            <span className="nf-profile-tab__icon"><NFLineIcon name={PROFILE_TAB_INFO[t.id]?.icon || "default"} size={17}/></span>
            <span>{t.label}</span>
          </button>
        ))}
      </div>

      <ClinicalStatusBanner paciente={paciente} onGo={setTab} onEvaluate={() => setShowEval(true)} onSession={onIniciarSesion} />

      {/* Tab content */}
      {tab === "info" && (
        <ClinicalCaseDashboard
          paciente={paciente}
          onGo={setTab}
          onStartSession={onIniciarSesion}
          onEvaluate={() => setShowEval(true)}
        />
      )}

      {tab === "datos" && (
        <NFPatientPersonalInfoEditor paciente={paciente} onUpdate={p => { setPac(p); }} />
      )}

      {tab === "hc" && (
        <HistoriaClinicaEditor paciente={paciente} onUpdate={p => { setPac(p); }} />
      )}

      {tab === "perfil-cognitivo" && (
        <div>
          {getActiveEvaluation(paciente)
            ? (
              <div>
                <PerfilCognitivoView evalData={getActiveEvaluation(paciente)} paciente={paciente} onIniciarSesion={() => setTab("intervencion")} />
                <div style={{ marginTop: 20 }}>
                  <CurrentVsInitialProfile paciente={paciente} />
                </div>
              </div>
            )
            : (
              <Card>
                <div style={{ textAlign: "center", padding: "40px 0" }}>
                  <div className="nf-empty-state-icon"><NFIcon name="brain" size={28} color={COLORS.cognitive}/></div>
                  <h3 style={{ fontWeight: 700, marginBottom: 8 }}>
                    {getEvaluationHistory(paciente).length ? "Sin línea base válida" : "Evaluación pendiente"}
                  </h3>
                  <p style={{ color: COLORS.textMuted, marginBottom: 20 }}>
                    {getEvaluationHistory(paciente).length
                      ? "Las evaluaciones conservadas no están activas como línea base. Realiza una nueva evaluación o restaura una evaluación válida del historial."
                      : "Este paciente aún no ha completado la evaluación cognitiva inicial."}
                  </p>
                  <BtnPrimary onClick={() => setShowEval(true)}>
                    {getEvaluationHistory(paciente).length ? "Realizar nueva evaluación" : "Iniciar evaluación ahora"}
                  </BtnPrimary>
                </div>
              </Card>
            )}

          <EvaluationHistoryManager
            paciente={paciente}
            onUpdate={setPac}
            onRepeat={() => {
              const ok = window.confirm(
                "Se realizará una nueva evaluación. La anterior se conservará en el historial y la nueva pasará a ser la línea base vigente. ¿Continuar?"
              );
              if (ok) setShowEval(true);
            }}
          />
        </div>
      )}

      {tab === "intervencion" && (
        getActiveEvaluation(paciente)
          ? <PerfilIntervencion
              paciente={paciente}
              onUpdate={p => setPac(p)}
              onIniciarSesion={onIniciarSesion}
            />
          : (
            <Card>
              <div style={{ textAlign: "center", padding: "40px 0" }}>
                <div className="nf-empty-state-icon"><NFLineIcon name="plan" size={27}/></div>
                <h3 style={{ fontWeight: 700, marginBottom: 8 }}>Primero realiza la evaluación</h3>
                <p style={{ color: COLORS.textMuted }}>El perfil de intervención se construye a partir de la evaluación y el criterio profesional.</p>
              </div>
            </Card>
          )
      )}

      {tab === "sesiones" && (
        <div className="nf-sessions">
          <div className="nf-section-head nf-v2-progress-head">
            <span className="nf-section-head__icon"><NFIcon name="calendar" size={20}/></span>
            <div>
              <h2>Sesiones</h2>
              <p>Historial clínico de las sesiones registradas para este paciente.</p>
            </div>
          </div>

          {!paciente.sesiones?.length ? (
            <Card>
              <div className="nf-empty-state">
                <div className="nf-empty-state-icon"><NFIcon name="calendar" size={27}/></div>
                <h3>Sin sesiones registradas</h3>
                <p>Cuando se complete la primera sesión aparecerá aquí su resumen clínico y acceso al reporte.</p>
              </div>
            </Card>
          ) : (
            <div className="nf-session-list">
              {[...paciente.sesiones].reverse().map((s, i) => (
                <Card key={`${s.numero}-${i}`} className="nf-session-card">
                  <div className="nf-session-card__main">
                    <div className="nf-session-card__marker"><NFIcon name="calendar" size={18}/><span className="nf-session-card__node"></span></div>
                    <div>
                      <div className="nf-session-card__title">
                        <h3>Sesión {s.numero}</h3>
                        <span>{new Date(s.date).toLocaleDateString("es", { day:"numeric", month:"short", year:"numeric" })}</span>
                      </div>
                      <div className="nf-session-card__metrics">
                        <div>
                          <span>Resultado</span>
                          {typeof s.gp === "number"
                            ? <strong style={{ color: gradeColor(s.gp) }}>{s.gp}%</strong>
                            : <strong style={{ color: COLORS.accent }}>Revisión clínica</strong>}
                        </div>
                        <div>
                          <span>Duración</span>
                          <strong>{fmt(s.secs || 0)}</strong>
                        </div>
                        <div>
                          <span>Registro</span>
                          <strong>{s.results?.length || 0} tarea(s)</strong>
                        </div>
                      </div>
                    </div>
                  </div>
                  <BtnSecondary onClick={() => { setReportSessionNumber(s.numero); setTab("reportes"); }}>
                    <span style={{display:"inline-flex",alignItems:"center",gap:7}}><NFIcon name="report" size={16}/>Ver reporte</span>
                  </BtnSecondary>
                </Card>
              ))}
            </div>
          )}
        </div>
      )}

      {tab === "progreso" && (
        <ProgressLongitudinal sesiones={paciente.sesiones || []} paciente={paciente} onSaveDecision={saveLongitudinalDecision} />
      )}

      {tab === "reportes" && (
        <ClinicalReportCenter
          paciente={paciente}
          initialSessionNumber={reportSessionNumber}
          onClearInitialSession={() => setReportSessionNumber(null)}
        />
      )}
    </>
  );
}


// ─── REPORTES CLÍNICOS INTEGRADOS ─────────────────────────────────────────────

// ─── FASE 19 · PERFIL INICIAL VS ACTUAL + GENERALIZACIÓN INTERNA ───────────────
function getInitialDomainPct(paciente, domId) {
  const baselineEval = getActiveEvaluation(paciente);
  const item = (baselineEval?.hist || []).find(h => h.id === domId);
  return item && typeof item.pct === "number" && !Number.isNaN(item.pct) ? item.pct : null;
}

function getCurrentDomainSnapshot(paciente, domId, maxSessions = 4) {
  const sesiones = paciente?.sesiones || [];
  const recent = [];
  for (let i = sesiones.length - 1; i >= 0 && recent.length < maxSessions; i--) {
    const d = sesiones[i]?.byDom?.[domId];
    if (!d) continue;
    const pct = typeof d.pct === "number"
      ? d.pct
      : (d.total > 0 ? Math.round((d.correct / d.total) * 100) : null);
    recent.unshift({
      numero: sesiones[i].numero,
      date: sesiones[i].date,
      pct,
      level: typeof d.averageAdaptiveLevel === "number" ? d.averageAdaptiveLevel : null,
      autonomy: typeof d.autonomyRate === "number" ? d.autonomyRate : null,
    });
  }
  const numeric = recent.filter(r => typeof r.pct === "number" && !Number.isNaN(r.pct));
  const currentPct = numeric.length ? Math.round(numeric.reduce((a,r)=>a+r.pct,0)/numeric.length) : null;
  return {
    recent,
    currentPct,
    recentSessions: recent.length,
    lastLevel: numeric.length ? numeric[numeric.length-1].level : null,
    lastAutonomy: numeric.length ? numeric[numeric.length-1].autonomy : null,
  };
}

function getExerciseImprovementEvidence(paciente, domId) {
  const byExercise = {};
  (paciente?.sesiones || []).forEach(s => {
    (s.results || []).forEach(r => {
      if (r.domId !== domId || typeof r.pct !== "number" || Number.isNaN(r.pct)) return;
      if (!byExercise[r.exId]) byExercise[r.exId] = [];
      byExercise[r.exId].push({ pct:r.pct, session:s.numero, date:s.date, level:r.adaptiveLevel ?? null });
    });
  });

  const exercises = Object.entries(byExercise).map(([exId,rows]) => {
    const first=rows[0], last=rows[rows.length-1];
    return {
      exId,
      attempts: rows.length,
      firstPct:first?.pct ?? null,
      lastPct:last?.pct ?? null,
      delta:first && last ? last.pct-first.pct : null,
      improved: rows.length>=2 && last.pct>first.pct,
    };
  });

  const distinctImproved=exercises.filter(x=>x.improved).length;
  const distinctMeasured=exercises.length;
  let evidenceType="insuficiente";
  let label="Datos insuficientes";
  let detail="Aún no hay suficientes repeticiones o variedad de tareas para describir un patrón de mejoría.";

  if (distinctImproved>=2) {
    evidenceType="dominio";
    label="Mejoría observada en diferentes tareas";
    detail=`Se observa mejoría en ${distinctImproved} ejercicios diferentes de este dominio. Esto describe generalización dentro de las tareas de NeuroFlex, no transferencia a actividades externas.`;
  } else if (distinctImproved===1) {
    evidenceType="especifica";
    label="Mejoría específica en una tarea";
    detail="La mejoría observada se concentra por ahora en un ejercicio repetido. Conviene comprobarla en otras tareas del mismo dominio.";
  } else if (distinctMeasured>=2) {
    evidenceType="variedad_sin_mejoria";
    label="Varias tareas observadas";
    detail="Existe información de diferentes ejercicios del dominio, pero todavía no se observa una mejoría consistente entre ellos.";
  }
  return { evidenceType,label,detail,distinctImproved,distinctMeasured,exercises };
}

function getCognitiveProfileEvolution(paciente) {
  return Object.keys(DOMINIOS_ADULTO).map(domId => {
    const initialPct=getInitialDomainPct(paciente,domId);
    const current=getCurrentDomainSnapshot(paciente,domId);
    const evidence=getExerciseImprovementEvidence(paciente,domId);
    const delta=initialPct!==null && current.currentPct!==null ? current.currentPct-initialPct : null;
    return {
      domId, initialPct, currentPct:current.currentPct, delta,
      recentSessions:current.recentSessions,
      lastLevel:current.lastLevel,
      lastAutonomy:current.lastAutonomy,
      evidence,
    };
  });
}

function CurrentVsInitialProfile({ paciente }) {
  const rows=getCognitiveProfileEvolution(paciente).filter(r=>r.initialPct!==null || r.currentPct!==null);
  if (!rows.length) return (
    <Card>
      <div className="nf-empty-state">
        <div className="nf-empty-state-icon"><NFLineIcon name="growth" size={27}/></div>
        <h3>Comparación aún no disponible</h3>
        <p>Aún no hay información suficiente para comparar el perfil inicial con el actual.</p>
      </div>
    </Card>
  );

  return (
    <div className="nf-cognitive-evolution">
      <div className="nf-section-head">
        <span className="nf-section-head__icon"><NFLineIcon name="growth" size={20}/></span>
        <div>
          <h2>Perfil inicial vs perfil actual</h2>
          <p>Comparación descriptiva entre la evaluación activa y hasta 4 sesiones recientes.</p>
        </div>
      </div>

      <Card className="nf-cognitive-evolution-note">
        <p>
          Las diferencias describen desempeño dentro de estas tareas y no equivalen por sí solas a cambio clínico general ni transferencia fuera de la plataforma.
        </p>
      </Card>

      <div className="nf-cognitive-evolution-list">
        {rows.map(r=>{
          const dom=DOMINIOS_ADULTO[r.domId];
          const trend=r.delta===null?"—":r.delta>0?`+${r.delta}`:String(r.delta);
          return (
            <Card key={r.domId} className="nf-cognitive-evolution-card">
              <div className="nf-cognitive-evolution-card__head">
                <div className="nf-cognitive-evolution-card__domain">
                  <span><NFLineIcon name={dom?.icon || "default"} size={17}/></span>
                  <div><h3>{dom?.label}</h3><p>{r.evidence.label}</p></div>
                </div>
                <div className="nf-cognitive-evolution-card__stats">
                  <div><small>Inicial</small><strong>{r.initialPct!==null?`${r.initialPct}%`:"—"}</strong></div>
                  <div><small>Actual</small><strong>{r.currentPct!==null?`${r.currentPct}%`:"—"}</strong></div>
                  <div><small>Cambio</small><strong style={{color:r.delta>0?COLORS.success:r.delta<0?COLORS.error:COLORS.textMuted}}>{r.delta!==null?`${trend} pts`:"—"}</strong></div>
                </div>
              </div>
              <div className="nf-cognitive-evolution-card__evidence">
                <p><strong>{r.evidence.label}:</strong> {r.evidence.detail}</p>
                {(r.lastLevel!==null || r.lastAutonomy!==null) && <span>
                  {r.lastLevel!==null?`Nivel reciente ${r.lastLevel}/5`:""}{r.lastLevel!==null&&r.lastAutonomy!==null?" · ":""}{r.lastAutonomy!==null?`Autonomía reciente ${r.lastAutonomy}%`:""}
                </span>}
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

function getDomainLongitudinalSummary(paciente, domId) {
  const sesiones = paciente?.sesiones || [];
  const rows = sesiones
    .map(s => {
      const d = s.byDom?.[domId];
      if (!d) return null;
      const pct = typeof d.pct === "number"
        ? d.pct
        : (d.total > 0 ? Math.round((d.correct / d.total) * 100) : null);
      return {
        numero: s.numero,
        date: s.date,
        pct,
        level: typeof d.averageAdaptiveLevel === "number" ? d.averageAdaptiveLevel : null,
        autonomy: typeof d.autonomyRate === "number" ? d.autonomyRate : null,
        support: typeof d.averageSupportLevel === "number" ? d.averageSupportLevel : null,
      };
    })
    .filter(Boolean);

  const cuantificables = rows.filter(r => typeof r.pct === "number");
  const first = cuantificables[0] || null;
  const last = cuantificables[cuantificables.length - 1] || null;

  return {
    sessions: rows.length,
    firstPct: first?.pct ?? null,
    lastPct: last?.pct ?? null,
    delta: first && last ? last.pct - first.pct : null,
    lastLevel: last?.level ?? null,
    lastAutonomy: last?.autonomy ?? null,
    pendingClinicalReview: rows.filter(r => r.pct === null).length,
  };
}

function getPatientReportSummary(paciente) {
  const sesiones = paciente?.sesiones || [];
  const cuantificables = sesiones.filter(s => typeof getSessionMetric(s, "taskIndicator") === "number");
  const first = cuantificables[0] || null;
  const last = cuantificables[cuantificables.length - 1] || null;
  const firstPct = first ? getSessionMetric(first, "taskIndicator") : null;
  const lastPct = last ? getSessionMetric(last, "taskIndicator") : null;

  const lastSession = sesiones[sesiones.length - 1] || null;
  const lastAutonomy = lastSession ? getSessionMetric(lastSession, "autonomyRate") : null;
  const lastLevel = lastSession ? getSessionMetric(lastSession, "averageAdaptiveLevel") : null;
  const lastTime = lastSession ? getSessionMetric(lastSession, "averageSecondsPerExercise") : null;

  return {
    totalSessions: sesiones.length,
    quantifiableSessions: cuantificables.length,
    firstPct,
    lastPct,
    delta: firstPct !== null && lastPct !== null ? lastPct - firstPct : null,
    lastAutonomy,
    lastLevel,
    lastTime,
  };
}


// ─── FASE 30 · SÍNTESIS CLÍNICA PROFESIONAL PARA REPORTES ────────────────────
// Redacción determinística basada únicamente en datos estructurados de NeuroFlex.
// No diagnostica, no usa baremos y evita inferir transferencia funcional.
function getReportActiveAreas(paciente) {
  return (paciente?.interventionPlan?.areas || [])
    .filter(a => ["objetivo","seguimiento"].includes(a.estado))
    .sort((a,b) => ({alta:0,media:1,baja:2}[a.prioridad] ?? 1) - ({alta:0,media:1,baja:2}[b.prioridad] ?? 1));
}

function buildEvolutionClinicalSynthesis(paciente) {
  const baseline = getActiveEvaluation(paciente);
  const summary = getPatientReportSummary(paciente);
  const activeAreas = getReportActiveAreas(paciente);
  const reviewAreas = (baseline?.hist || []).filter(h => h.requiresReview || typeof h.pct !== "number");
  const recent = (paciente?.sesiones || []).slice(-3);
  const trackedAutonomy = recent
    .map(s => getSessionMetric(s, "autonomyRate"))
    .filter(v => typeof v === "number");
  const trackedLevel = recent
    .map(s => getSessionMetric(s, "averageAdaptiveLevel"))
    .filter(v => typeof v === "number");
  const avgAutonomy = safeAverage(trackedAutonomy);
  const avgLevel = safeAverage(trackedLevel);

  const observations = [];
  if (!baseline) {
    observations.push("No hay una línea base válida activa; por ello no corresponde interpretar un perfil inicial ni atribuir cambios a la intervención.");
  } else {
    observations.push(`La línea base vigente explora ${baseline.hist?.length || 0} dominios de NeuroFlex${reviewAreas.length ? `, con ${reviewAreas.length} área(s) que requieren valoración profesional y no se incorporan automáticamente a indicadores porcentuales` : ""}.`);
  }

  if (summary.quantifiableSessions >= 2 && summary.delta !== null) {
    if (summary.delta > 0) observations.push(`Entre la primera y la sesión cuantificable más reciente se observa un cambio descriptivo de +${summary.delta} puntos en el indicador de tareas.`);
    else if (summary.delta < 0) observations.push(`Entre la primera y la sesión cuantificable más reciente se observa un cambio descriptivo de ${summary.delta} puntos; conviene interpretarlo junto con dificultad, apoyos y características de las tareas administradas.`);
    else observations.push("El indicador de tareas se mantiene sin cambio porcentual entre la primera y la sesión cuantificable más reciente.");
  } else if (summary.totalSessions > 0) {
    observations.push("Aún no hay suficientes sesiones cuantificables para describir una tendencia longitudinal estable.");
  } else {
    observations.push("Aún no se registran sesiones de intervención para describir evolución.");
  }

  if (avgAutonomy !== null) observations.push(`En las sesiones recientes con registro de apoyos, la autonomía media observada es aproximadamente ${Math.round(avgAutonomy)}%.`);
  if (avgLevel !== null) observations.push(`El nivel adaptativo medio reciente registrado es ${Math.round(avgLevel*10)/10}/5; este dato describe la dificultad administrada y no una puntuación normativa.`);
  if (activeAreas.length) observations.push(`El plan vigente prioriza ${activeAreas.slice(0,4).map(a => DOMINIOS_ADULTO[a.id]?.label).filter(Boolean).join(", ")}${activeAreas.length > 4 ? " y otras áreas" : ""}.`);

  if (baseline?.assessmentVersion === NEUROFLEX_ASSESSMENT_VERSION) {
    buildIntegratedLongitudinalSynthesisV2(paciente).forEach(x => {
      if (!observations.includes(x)) observations.push(x);
    });
  }

  return observations;
}

function buildSessionClinicalSynthesis(sesion) {
  const results = sesion?.results || [];
  const indicator = getSessionMetric(sesion, "taskIndicator");
  const autonomy = getSessionMetric(sesion, "autonomyRate");
  const level = getSessionMetric(sesion, "averageAdaptiveLevel");
  const review = results.filter(r => r.requiresReview || typeof r.pct !== "number").length;
  const supportUsed = results.filter(r => {
    const v = getTrackedSupportLevel(r);
    return typeof v === "number" && v > 0;
  }).length;
  const meta = sesion?.metacognitionSummary;

  const observations = [];
  observations.push(
    indicator !== null
      ? `La sesión presenta un indicador descriptivo de tareas de ${indicator}%, calculado únicamente con ejercicios cuantificables.`
      : "La sesión no presenta un indicador porcentual global cuantificable; los registros deben revisarse a partir de sus métricas específicas y valoración profesional."
  );
  if (review) observations.push(`${review} ejercicio(s) requieren valoración profesional y no se interpretan automáticamente como aciertos o errores porcentuales.`);
  if (autonomy !== null) observations.push(`La autonomía registrada fue ${autonomy}%${supportUsed ? `, con uso de apoyo en ${supportUsed} ejercicio(s)` : ", sin apoyos registrados en los ejercicios trazados"}.`);
  if (level !== null) observations.push(`La dificultad media administrada fue nivel ${level}/5; debe interpretarse junto con precisión, tiempo y necesidad de apoyo.`);
  if (meta?.preferredStrategy) observations.push(`En el registro metacognitivo, la estrategia referida con mayor frecuencia fue “${meta.preferredStrategy}”. Este dato corresponde a autorreporte durante la sesión.`);
  return observations;
}

function ClinicalSynthesisBlock({ title = "Síntesis profesional", observations = [] }) {
  if (!observations.length) return null;
  return (
    <div style={{ marginTop: 16, padding: 14, borderRadius: 10, border: "1px solid #dfe3ea", background: "#fbfcfe" }}>
      <div style={{ fontWeight: 850, fontSize: ".82rem", marginBottom: 7 }}>{title}</div>
      {observations.map((x,i) => (
        <p key={i} style={{ margin: i ? "5px 0 0" : 0, fontSize: ".73rem", color: "#475467", lineHeight: 1.55 }}>{x}</p>
      ))}
    </div>
  );
}

function ReportDisclaimer() {
  return (
    <div style={{ marginTop: 18, padding: 12, borderRadius: 10, background: "#f7f8fb", border: "1px solid #e6e8ef", fontSize: ".72rem", color: "#667085", lineHeight: 1.55 }}>
      Los resultados presentados describen exclusivamente el desempeño observado en las tareas administradas mediante NeuroFlex.
      No corresponden a puntuaciones normativas, no sustituyen instrumentos neuropsicológicos estandarizados y no constituyen por sí solos un diagnóstico.
      Los cambios observados dentro de la plataforma no demuestran automáticamente generalización a actividades de la vida diaria.
      La interpretación final debe integrarse con antecedentes, observación clínica, funcionamiento cotidiano y juicio profesional.
    </div>
  );
}


